"""ResourcePackBuilder.java へ Java 1.21.9／1.21.10（プロトコル773）の対応を入れる。

pack_format 69（リソースパック）は Minecraft Wiki の pack_format 表で
確認した値。772の流儀をなぞる：PACK_FORMAT_1_21_7／PACK_FILE_NAME_772／
PACK_MCMETA_772／build772／writePack772 の直後に773版を増やす。
各アンカーはファイル中にちょうど1回だけ現れること。
"""
import sys
from pathlib import Path

PATH = Path(__file__).resolve().parent.parent / "src" / "main" / "java" \
    / "io" / "detergentmc" / "protocol" / "ResourcePackBuilder.java"


def edit(path, pairs):
    src = path.read_text(encoding="utf-8")
    for label, old, new in pairs:
        n = src.count(old)
        if n != 1:
            print(f"NG: {label}: anchor が {n} 回見つかった（1回のはず）", file=sys.stderr)
            sys.exit(1)
        src = src.replace(old, new, 1)
        print(f"OK: {label}")
    path.write_text(src, encoding="utf-8")


